    const by = new Map(); for (const e of wk.events) { if (e.impact !== 'high' && e.impact !== 'medium') continue; const k = new Date(e.ms).toLocaleDateString('en-CA', { timeZone: 'Europe/London' }); (by.get(k) ?? by.set(k, []).get(k)).push(e); }
