    const COT_FOR = { NQ: ['NQ'], SPX500: ['ES'], US30: ['YM'], US2000: ['RTY'], GOLD: ['GOLD'], BTCUSD: ['BTC'], EURUSD: ['EUR'], GBPUSD: ['GBP'], USDJPY: ['JPY'], AUDUSD: ['AUD'], USDCAD: ['CAD'], USDCHF: ['CHF'], NZDUSD: ['NZD'] };
    const cotRow = (COT_FOR[key] ?? []).map(sy => crMap[sy]).filter(Boolean).map(c => `<div class="cot2"><span><b>${/^[A-Z]{3}$/.test(c.sym) ? c.sym + ' speculators' : 'Speculators'}:</b> ${esc(c.state === 'mid-range' ? 'mid-range' : POS_WORD[c.state] ?? c.state)}<small>${ord(c.pct)} percentile of their history</small></span>${posGaugeSm(c)}</div>`).join('');
