  const ranges = pairCards ? sec('Each market at a glance', 'Part 3 · Pair by pair', `<div class="pcg">${pairCards}</div><p class="small muted">Bar: how much of a normal day's range is used. ${weekly ? `Strips: one block per day over the last 30 days, newest on the right, <b style="color:${STATE_COLOUR.quiet}">blue quiet</b>, <b style="color:${STATE_COLOUR.active}">amber active</b>, grey no reading. They describe how big the moves were, not which way. ` : `Strips: one block per hour, newest on the right, <b style="color:${STATE_COLOUR.quiet}">blue choppy or quiet</b>, <b style="color:${STATE_COLOUR.up}">green a bullish hour</b>, <b style="color:${STATE_COLOUR.down}">red a bearish hour</b>, grey no reading. They describe the hour that passed, not what comes next. `}Positioning: where speculators sit in their own history, from the weekly CFTC report. Option zone: where the biggest option positions sit, a place and not a magnet; the dealer note is tested on the S&P 500 only.</p>`) : '';

