    const textbook = (a.transmission ?? []).length ? `<table class="tx"><tr><th style="width:22%">Market</th><th>What the textbook says</th><th>What happened</th></tr>${a.transmission.slice(0, 5).map(t => `<tr><td><b>${esc(clipS(t.asset ?? '', 40))}</b></td><td>${esc(clipS(t.should ?? '', 150))}</td><td>${esc(clipS(t.is ?? '', 170))}</td></tr>`).join('')}</table>` : '';
