        const sc = v => Number.isFinite(v) ? v : null, sgn = (v, d = 1) => `${v > 0 ? '+' : v < 0 ? '−' : ''}${Math.abs(v).toFixed(d)}`, cls = v => (v > 0 ? 'up' : v < 0 ? 'dn' : ''), clsFear = v => (v > 0 ? 'dn' : v < 0 ? 'up' : '');
        // B. the world: sectors and the big companies as dark bar figures, commodities as tiles, fear and credit as flat tables
        const SECNOTE = { Energy: 'follows oil', Technology: 'where the Nasdaq sits', Semiconductors: "the Nasdaq's engine", Utilities: 'defensive', 'Consumer staples': 'defensive', 'Health care': 'defensive' };
        const sect = barFigure('Sectors, last 20 days', [...(stk?.sectors ?? [])].filter(x => x.d20 != null).sort((a, b) => b.d20 - a.d20).map(x => ({ label: x.label, v: x.d20, sub: sc(x.d1), note: SECNOTE[x.label] ?? '' })), Hh, { note: 'Each bar is the 20-day move of a sector fund, with today\'s move beside it.' });
        const mega = barFigure('The big companies that carry the Nasdaq', [...(stk?.mega ?? [])].filter(x => x.d20 != null).sort((a, b) => b.d20 - a.d20).map(x => ({ label: x.label, v: x.d20, sub: sc(x.d1) })), Hh, { note: 'A handful of very large technology companies explain much of the Nasdaq\'s day.' });
        const fearT = vo.length ? flatTable(['Fear gauge', 'Level', 'Today', '20 days'], vo.map(x => [esc(x.label), x.v.toFixed(1), `<span class="${clsFear(x.d1)}">${x.d1 != null ? sgn(x.d1) : ''}</span>`, `<span class="${clsFear(x.d20)}">${x.d20 != null ? sgn(x.d20) : ''}</span>`])) : '';
        const credT = cr2.length ? flatTable(['Borrowing cost over government bonds', 'Level', 'Today', '20 days'], cr2.map(x => [esc(x.label), `${Math.round(x.bp)}bp`, `<span class="${clsFear(x.d1)}">${x.d1 != null ? sgn(x.d1, 0) + 'bp' : ''}</span>`, `<span class="${clsFear(x.d20)}">${x.d20 != null ? sgn(x.d20, 0) + 'bp' : ''}</span>`])) : '';
        const worldHtml = `${dsec('Stocks under the hood', 'observed', '', `${sect}${mega}`, sectorNote(stk?.sectors, stk?.mega, mv), true)}${dsec('Commodities, fear and credit', 'observed', 'For fear gauges and credit a rise is shown in red: higher means more worry.', `${G(gd(cmNote))}${cm.length ? tileRow(cm, Hh) : ''}${G(gd(fearNote(vo, cr2, n.riskFlags)))}<div class="two"><div>${fearT}</div><div>${credT}</div></div>`, null, true)}`;
        // C. the currencies: one league figure and one table, not eight cards
        const ccyRows = [...(n.strengths ?? [])].sort((a, b) => b.score - a.score).map(s0 => { const ccy = s0.ccy, c = cbMap[ccy], su = surFull[ccy], cr = crMap[ccy], stance = c?.regime ? c.regime.charAt(0) + c.regime.slice(1).toLowerCase() : null;
          return [`${flagSvg(ccy, 22, 15)} <b>${esc(ccy)}</b>`, `<span class="${cls(s0.score)}">${sgn(s0.score, 2)}%</span>`, c ? `${esc(CCY_BANK[ccy] ?? c.bank ?? '')}${stance ? ` <i style="font-style:normal;color:#9a6200">${esc(stance)}</i>` : ''}` : `<span style="color:#9aa8bb">tone not tracked</span>`, su ? `<span class="${cls(su.score)}">${sgn(su.score, 2)}</span>` : '', cr ? esc(cr.state === 'mid-range' ? 'mid-range' : cr.state) : '', c ? esc(clipS(c.headline ?? '', 120)) : '']; });
        const ccyCards = [...(n.strengths ?? [])].sort((x, y) => y.score - x.score).map(s0 => currencyCard(currencyNarrative(s0.ccy, NARR), Hh, flagSvg(s0.ccy, 30, 21))).join('');
        const ccyHtml = ccyRows.length ? `${barFigure('Currency league table, today', [...(n.strengths ?? [])].sort((a, b) => b.score - a.score).map(s0 => ({ label: s0.ccy, v: s0.score, note: s0.ccy === 'USD' ? 'the dollar' : '' })), Hh, { note: 'Average one-day move against the other currencies tracked. Green is stronger, red is weaker.' })}${ccyCards}<p class="small muted" style="margin:2px 0 8px">The cards describe what each currency's inputs say today. None of them is a view on direction: the desk's tests found direction calls from these inputs close to a coin flip.</p>${flatTable(['Currency', 'Today', 'Central bank', 'Data surprises', 'Speculators'], ccyRows.map(r => r.slice(0, 5)), ['l', 'r', 'l', 'r', 'l'])}` : '';
        // D. every market, one row each
